export declare const TIMELINE_STYLES = "\n  .recap-panel-tl-row:hover {\n    background: var(--accent) !important;\n  }\n  .recap-panel-filter-bar {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    padding: 6px 8px;\n    background: var(--muted);\n    border: 1px solid var(--border);\n    border-radius: calc(var(--radius) - 2px);\n    font-size: 11px;\n    color: var(--foreground);\n    margin-bottom: 10px;\n  }\n  .recap-panel-filter-bar strong {\n    color: var(--foreground);\n    font-weight: 600;\n  }\n  .recap-panel-filter-clear {\n    background: none;\n    border: none;\n    color: var(--muted-foreground);\n    cursor: pointer;\n    font-size: 11px;\n    font-family: inherit;\n    padding: 0;\n    margin-left: auto;\n  }\n  .recap-panel-filter-clear:hover { color: var(--foreground); }\n  .recap-panel-tabs {\n    display: inline-flex;\n    gap: 2px;\n    background: var(--muted);\n    border-radius: calc(var(--radius) - 2px);\n    padding: 3px;\n    margin-bottom: 12px;\n    flex-shrink: 0;\n  }\n  .recap-panel-tab {\n    background: none;\n    border: none;\n    border-radius: calc(var(--radius) - 4px);\n    color: var(--muted-foreground);\n    cursor: pointer;\n    font-size: 12px;\n    font-weight: 500;\n    font-family: inherit;\n    padding: 5px 12px;\n    transition: color 0.15s, background 0.15s, box-shadow 0.15s;\n  }\n  .recap-panel-tab:hover { color: var(--foreground); }\n  .recap-panel-tab.active {\n    background: var(--background);\n    color: var(--foreground);\n    box-shadow: 0 1px 2px rgba(0,0,0,0.3);\n  }\n";
